import{_ as e,o as d,c as o,a2 as r}from"./chunks/framework.D9E58p8B.js";const m=JSON.parse('{"title":"Référence des outils MCP","description":"","frontmatter":{"title":"Référence des outils MCP"},"headers":[],"relativePath":"reference/index.md","filePath":"reference/index.md"}'),a={name:"reference/index.md"};function n(i,t,s,c,l,u){return d(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="reference-des-outils-mcp" tabindex="-1">Référence des outils MCP <a class="header-anchor" href="#reference-des-outils-mcp" aria-label="Permalink to &quot;Référence des outils MCP&quot;">​</a></h1><p>Cette section décrit les 33 outils publics que Daimon expose à votre client IA par le protocole MCP, en stdio. Daimon est un organe local de perception et d&#39;action : il ne fait appel à aucune IA lui-même et ne répond que lorsque votre client l&#39;interroge.</p><p>Les valeurs par défaut citées sont celles du code ; en cas d&#39;écart, le code fait foi.</p><h2 id="les-organes" tabindex="-1">Les organes <a class="header-anchor" href="#les-organes" aria-label="Permalink to &quot;Les organes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Organe</th><th>Rôle</th><th>Outils</th><th>Page</th></tr></thead><tbody><tr><td>Vue</td><td>Voir l&#39;écran : captures, conversion de coordonnées, localisation de texte, profils d&#39;écrans</td><td>8</td><td><a href="./vue.html">Vue</a></td></tr><tr><td>Touché</td><td>Lire l&#39;arbre d&#39;accessibilité : éléments, rôles, libellés</td><td>2</td><td><a href="./touche.html">Touché</a></td></tr><tr><td>Mains</td><td>Agir : cliquer, saisir, faire défiler, glisser, piloter les fenêtres</td><td>15</td><td><a href="./mains.html">Mains</a></td></tr><tr><td>Overlay</td><td>Montrer à la personne devant l&#39;écran ce que fait l&#39;IA</td><td>5</td><td><a href="./overlay.html">Overlay</a></td></tr><tr><td>Diagnostic</td><td>Vérifier l&#39;état de la machine et le plafond d&#39;autorisation</td><td>2, plus <code>ping</code></td><td><a href="./diagnostic.html">Diagnostic</a></td></tr></tbody></table><h2 id="tableau-des-33-outils" tabindex="-1">Tableau des 33 outils <a class="header-anchor" href="#tableau-des-33-outils" aria-label="Permalink to &quot;Tableau des 33 outils&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Outil</th><th>Organe</th><th>Niveau requis</th></tr></thead><tbody><tr><td><code>vue_displays</code></td><td>Vue</td><td>lecture</td></tr><tr><td><code>vue_snapshot</code></td><td>Vue</td><td>lecture</td></tr><tr><td><code>vue_resolve</code></td><td>Vue</td><td>lecture</td></tr><tr><td><code>vue_find</code></td><td>Vue</td><td>lecture</td></tr><tr><td><code>vue_calibrate</code></td><td>Vue</td><td>lecture (enregistre un profil d&#39;écrans)</td></tr><tr><td><code>vue_profile</code></td><td>Vue</td><td>lecture</td></tr><tr><td><code>vue_profile_brief</code></td><td>Vue</td><td>lecture</td></tr><tr><td><code>vue_pilot_brief</code></td><td>Vue</td><td>lecture</td></tr><tr><td><code>touche_tree</code></td><td>Touché</td><td>lecture</td></tr><tr><td><code>touche_probe</code></td><td>Touché</td><td>lecture</td></tr><tr><td><code>main_navigate</code></td><td>Mains</td><td>L1</td></tr><tr><td><code>main_hover</code></td><td>Mains</td><td>L1</td></tr><tr><td><code>main_activate</code></td><td>Mains</td><td>L1</td></tr><tr><td><code>main_window_minimize</code></td><td>Mains</td><td>L1</td></tr><tr><td><code>main_window_hide</code></td><td>Mains</td><td>L1</td></tr><tr><td><code>main_window_show</code></td><td>Mains</td><td>L1</td></tr><tr><td><code>main_click</code></td><td>Mains</td><td>L2</td></tr><tr><td><code>main_type</code></td><td>Mains</td><td>L2</td></tr><tr><td><code>main_drag</code></td><td>Mains</td><td>L2</td></tr><tr><td><code>main_key</code></td><td>Mains</td><td>L2</td></tr><tr><td><code>main_press</code></td><td>Mains</td><td>L3</td></tr><tr><td><code>main_mouse_down</code></td><td>Mains</td><td>L4</td></tr><tr><td><code>main_mouse_up</code></td><td>Mains</td><td>L4</td></tr><tr><td><code>main_key_down</code></td><td>Mains</td><td>L4</td></tr><tr><td><code>main_key_up</code></td><td>Mains</td><td>L4</td></tr><tr><td><code>overlay_highlight</code></td><td>Overlay</td><td>aucun (présentation)</td></tr><tr><td><code>overlay_spotlight</code></td><td>Overlay</td><td>aucun (présentation)</td></tr><tr><td><code>overlay_cursor</code></td><td>Overlay</td><td>aucun (présentation)</td></tr><tr><td><code>overlay_banner</code></td><td>Overlay</td><td>aucun (présentation)</td></tr><tr><td><code>overlay_clear</code></td><td>Overlay</td><td>aucun (présentation)</td></tr><tr><td><code>daimon_doctor</code></td><td>Diagnostic</td><td>lecture</td></tr><tr><td><code>main_ceiling</code></td><td>Diagnostic</td><td>lecture</td></tr><tr><td><code>ping</code></td><td>Diagnostic (annexe)</td><td>lecture</td></tr></tbody></table><h2 id="les-niveaux-d-autorisation" tabindex="-1">Les niveaux d&#39;autorisation <a class="header-anchor" href="#les-niveaux-d-autorisation" aria-label="Permalink to &quot;Les niveaux d&#39;autorisation&quot;">​</a></h2><p>Les outils de perception, d&#39;overlay et de diagnostic ne sont jamais soumis au plafond. Seuls les 15 outils d&#39;action des Mains le sont. Le plafond est un réglage humain : une IA ne peut jamais le relever, et un outil situé au-dessus du plafond est refusé.</p><table tabindex="0"><thead><tr><th>Niveau</th><th>Nom interne</th><th>Ce qu&#39;il autorise</th></tr></thead><tbody><tr><td>L0</td><td><code>READ</code></td><td>Regarder uniquement, aucune action</td></tr><tr><td>L1</td><td><code>NONDESTRUCTIVE</code></td><td>Défilement, survol, activation et masquage de fenêtres</td></tr><tr><td>L2</td><td><code>INPUT</code></td><td>Clic, saisie, touches, glisser-déposer</td></tr><tr><td>L3</td><td><code>VALIDATION</code></td><td>Activation d&#39;un bouton engageant (<code>main_press</code>)</td></tr><tr><td>L4</td><td><code>AUTONOMOUS</code></td><td>Primitives bas niveau : maintien de souris et de touches</td></tr></tbody></table><p>Le niveau effectif d&#39;un appel peut être relevé par la cible (par exemple, un dépôt sur la Corbeille), jamais abaissé sous le niveau nominal du tableau ci-dessus. Un nom d&#39;outil inconnu est traité comme une lecture et ne relève jamais le plafond. Pour connaître le plafond actif, appelez <code>main_ceiling</code> (voir <a href="./diagnostic.html">Diagnostic</a>).</p><h2 id="conventions-communes" tabindex="-1">Conventions communes <a class="header-anchor" href="#conventions-communes" aria-label="Permalink to &quot;Conventions communes&quot;">​</a></h2><p><strong>Coordonnées.</strong> Vue et Mains parlent en <strong>points</strong> : l&#39;unité du bureau global, celle que renvoient <code>vue_find</code> et <code>vue_resolve</code> et que le pointeur utilise. Sur un écran Retina, un point correspond à plusieurs pixels de l&#39;image servie ; <code>image_scale</code> donne le nombre de pixels d&#39;image <strong>par point</strong>. Sous Windows, un point est un pixel physique de l&#39;écran virtuel et <code>backing_scale</code> vaut toujours 1.0. Les coordonnées de l&#39;Overlay sont, elles, des pixels globaux bruts : voir <a href="./overlay.html">Overlay</a>.</p><p><strong>Région.</strong> Un paramètre <code>region</code> est un rectangle <code>{x, y, width, height}</code> en points, <strong>local à l&#39;écran choisi</strong> (l&#39;origine est le coin haut-gauche de cet écran, pas du bureau). Il est borné à l&#39;écran ; un rectangle de surface nulle ne capture rien.</p><p><strong>Espace d&#39;image.</strong> Les outils de Mains qui prennent un point acceptent <code>space=&quot;image&quot;</code> avec <code>display=k</code> : vous donnez les pixels d&#39;un <code>vue_snapshot</code> et Daimon résout lui-même le point global. Passez alors les mêmes <code>max_width</code> et <code>region</code> que ceux du snapshot.</p><p><strong>Réponses.</strong> Les réponses sont des objets JSON structurés. Une erreur de l&#39;organe Vue ou de résolution de point prend la forme <code>{&quot;error&quot;: &quot;&lt;code&gt;&quot;, &quot;message&quot;: &quot;&lt;détail&gt;&quot;}</code>. Les Mains renvoient <code>{&quot;status&quot;: &quot;refused&quot; | &quot;done&quot; | &quot;error&quot;, ...}</code> : voir <a href="./mains.html">Mains</a>.</p><p><strong>Présence à l&#39;écran.</strong> Chaque appel d&#39;outil allume d&#39;abord la marque de présence, afin que la personne devant l&#39;écran sache qu&#39;une IA utilise Daimon, pour regarder comme pour agir.</p><p><strong>Confidentialité.</strong> Les applications protégées par vos exclusions sont censurées dans les captures, et les contenus sensibles sont expurgés des arbres d&#39;accessibilité. Le texte saisi par <code>main_type</code> n&#39;est jamais écrit dans le journal d&#39;audit.</p>',18)])])}const h=e(a,[["render",n]]);export{m as __pageData,h as default};
